    binding.handlePointerEvent(
      PointerDownEvent(
        pointer: pointer,
        position: start,
        kind: pointerKind,
        buttons: kPrimaryButton,
        timeStamp: t0,
      ),
    );

    for (var i = 1; i <= steps; i++) {
      final p = Offset(
        start.dx + (dx * i / steps),
        start.dy + (dy * i / steps),
      );
      final ts = t0 + Duration(milliseconds: 8 * i);
      binding.handlePointerEvent(
        PointerMoveEvent(
          pointer: pointer,
          position: p,
          kind: pointerKind,
          buttons: kPrimaryButton,
          timeStamp: ts,
        ),
      );
    }

    final end = Offset(start.dx + dx, start.dy + dy);
    final tEnd = t0 + Duration(milliseconds: 8 * (steps + 1));

    if (hold) {
      _heldDragPointer = pointer;
      _heldDragLastPosition = end;
      _heldDragKind = pointerKind;
